mapper.update:
UPDATE product_physical_ext
SET stock          = #{stock},
    delivery_type  = #{deliveryType},
    refund_rule    = #{refundRule},
    updated_at     = #{updatedAt}
WHERE product_id = #{productId}

UPDATE product_virtual_ext
SET valid_days          = #{validDays},
    verification_type   = #{verificationType},
    store_ids            = #{storeIds, typeHandler=com.example.product.repository.typehandler.LongListJsonTypeHandler},
    updated_at           = #{updatedAt}
WHERE product_id = #{productId}

UPDATE product_material_ext
SET media_type        = #{mediaType},
    media_url         = #{mediaUrl},
    license_end_time = #{licenseEndTime},
    updated_at        = #{updatedAt}
WHERE product_id = #{productId}
